-- Din Felsefesi 2, bahar 6. hafta: yeniden yazılan Zapoot ve Quiz soruları (yeni paketler). Kaynak: docs/soru-onerileri/yeni/bahar-06.txt. Aynı soru metni varsa atlanır.
do $$
declare v_icerik uuid;
begin
  select id into v_icerik from public.subjects where ad = 'Din Felsefesi 2' limit 1;
  if v_icerik is null then raise exception 'Din Felsefesi 2 içeriği bulunamadı'; end if;
  insert into public.questions (subject_id, soru, dogru, yanlislar, sure_sn, ek)
  select v_icerik, p[3], p[4], array[p[5], p[6], p[7]], case when p[2] = 'Z' then 20 else 60 end,
         jsonb_build_object('paket', p[1] || '. hafta: ' || case when p[2] = 'Z' then 'Zapoot (yeni, 20 soru)' else 'Quiz (yeni, 15 soru)' end, 'konu', p[8], 'zorluk', p[9], 'bloom', p[10])
  from (select string_to_array(l, '|') as p from unnest(string_to_array($q$
